"""what the rules come to, as something to look up: every theorem, keyed by theory and then by question, as JSON text"""
theorems_json() = read(joinpath(@__DIR__, "theorems.json"), String)

# while the package is compiled, once for this machine, the medium is run a little, so that its programs are compiled
# then and kept with the package - not again on every first run. Nothing is kept of what it computes.
if ccall(:jl_generating_output, Cint, ()) == 1
  let h = Rt.held()
    try
      m = medium(G, 11, 96, 3, 8, 1)
      m.local_rays = true
      add(m, Hole(x = 5, y = 5, mx = 0.3, ways = 1))
      seed(m)
      tick(m)
    catch
    finally
      Rt.restore!(h)
    end
  end
end

